const test = require('node:test');
const assert = require('node:assert/strict');
const { sum } = require('../src/sum.js');

test('sum adds positive numbers', () => {
  assert.equal(sum(2, 3), 5);
});

test('sum handles zero in either position', () => {
  assert.equal(sum(0, 5), 5);
  assert.equal(sum(5, 0), 5);
  assert.equal(sum(0, 0), 0);
});

test('sum handles negative numbers', () => {
  assert.equal(sum(-2, -3), -5);
  assert.equal(sum(-2, 3), 1);
  assert.equal(sum(2, -3), -1);
});

test('sum adds fractional numbers', () => {
  assert.equal(sum(1.5, 2.25), 3.75);
});
